GRANT SELECT                 ON TABLE task.vw_tasks_enriched TO task_svc;

-- task per-product role model (P1.1)
GRANT SELECT                 ON TABLE task.roles         TO task_svc;
GRANT SELECT, INSERT, UPDATE ON TABLE task.member_roles  TO task_svc;
GRANT SELECT                 ON TABLE task.vw_member_roles TO task_svc;

ALTER DEFAULT PRIVILEGES IN SCHEMA task GRANT SELECT, INSERT, UPDATE ON TABLES TO task_svc;

-- EXECUTE grants — the resolver runs on each caller's own login role (the *_svc
-- logins are NOINHERIT, so an app_user-only grant would NOT reach them via
-- membership without SET ROLE). Grant directly to every login that resolves that
-- product's rank, plus app_user/tenant_admin for SET ROLE paths. Mirrors the
-- explicit EXECUTE grants on iam.fn_user_org_rank (script 01).
--   lms.fn_member_role  → lms_svc (leads/meta), lead_svc (gateway + notifications)
--   hr.fn_member_role   → hr_svc
--   task.fn_member_role → task_svc
GRANT EXECUTE ON FUNCTION lms.fn_member_role(UUID, UUID)  TO app_user, tenant_admin, lms_svc, lead_svc;
GRANT EXECUTE ON FUNCTION hr.fn_member_role(UUID, UUID)   TO app_user, tenant_admin, hr_svc;
GRANT EXECUTE ON FUNCTION task.fn_member_role(UUID, UUID) TO app_user, tenant_admin, task_svc;

-- Tier C: every product service now resolves role/rank/department from the one
-- iam ladder via iam.fn_user_org_role (see 02_schema.sql), so each product login
-- needs EXECUTE on it. Declared here because these logins are created after 02.
GRANT EXECUTE ON FUNCTION iam.fn_user_org_role(UUID, UUID) TO lms_svc, hr_svc, task_svc, lead_svc;

-- Tier C3: same for the capability matrix, which every service loads at startup.
GRANT EXECUTE ON FUNCTION iam.fn_role_capability_matrix(UUID) TO lms_svc, hr_svc, task_svc, lead_svc;

-- ===================================================================
-- readonly_user membership for every app-pool login (P0 #1 defense-in-depth)
--
-- withRoleTx does `SET LOCAL ROLE readonly_user` for read_only actors. A login
-- may only SET ROLE to a role it is a member of, so grant readonly_user to every
-- login that can currently become app_user. Done dynamically so future *_svc
-- logins are covered without editing this list. readonly_user is itself a member
-- of app_user (see 01) and is excluded.
-- ===================================================================
DO $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT m.rolname
    FROM pg_auth_members am
    JOIN pg_roles m ON m.oid = am.member
    JOIN pg_roles g ON g.oid = am.roleid
    WHERE g.rolname = 'app_user' AND m.rolname <> 'readonly_user'
  LOOP
    EXECUTE format('GRANT readonly_user TO %I', r.rolname);
  END LOOP;
END $$;


-- ═══════════════════════════════════════════════════════════════════
-- 4. GRANTs
--    Registry tables are global reference data (no tenant_id, no RLS):
--    readable by subject roles for a future "preview defaults" UI, written
--    only by root_service. tenant_catalog_versions is SELECT-only for
--    subject roles; root_service (the seeder) writes it.
-- ═══════════════════════════════════════════════════════════════════
GRANT SELECT         ON entity.catalog_defaults, entity.catalog_versions TO app_user;
GRANT SELECT         ON entity.catalog_defaults, entity.catalog_versions TO tenant_admin;
GRANT ALL PRIVILEGES ON entity.catalog_defaults, entity.catalog_versions TO root_service;

GRANT SELECT         ON entity.tenant_catalog_versions TO app_user;
GRANT SELECT         ON entity.tenant_catalog_versions TO tenant_admin;
GRANT ALL PRIVILEGES ON entity.tenant_catalog_versions TO root_service;


-- ═══════════════════════════════════════════════════════════════════
-- 8. Function privileges — these functions cross tenant boundaries and
--    must only run as the BYPASSRLS service account (called from
--    @crm/db's withServiceTx at provisioning / from the tenant-scoped
--    reset path). Revoke the default PUBLIC EXECUTE so a subject role
--    (app_user / tenant_admin) can never invoke cross-tenant seeding.
-- ═══════════════════════════════════════════════════════════════════
REVOKE ALL ON FUNCTION entity._apply_catalog_rows(UUID, TEXT, INT, BOOLEAN) FROM PUBLIC;
REVOKE ALL ON FUNCTION entity.seed_tenant_defaults(UUID)                     FROM PUBLIC;
REVOKE ALL ON FUNCTION entity.reset_tenant_catalog(UUID, TEXT, INT)          FROM PUBLIC;
GRANT EXECUTE ON FUNCTION entity._apply_catalog_rows(UUID, TEXT, INT, BOOLEAN) TO root_service;
GRANT EXECUTE ON FUNCTION entity.seed_tenant_defaults(UUID)                     TO root_service;
GRANT EXECUTE ON FUNCTION entity.reset_tenant_catalog(UUID, TEXT, INT)          TO root_service;
GRANT INSERT, UPDATE ON TABLE lms.roles TO lms_svc;
GRANT INSERT, UPDATE ON TABLE hr.leave_types TO hr_svc;
GRANT INSERT, UPDATE ON TABLE hr.employment_types TO hr_svc;
GRANT INSERT, UPDATE ON TABLE hr.attendance_statuses TO hr_svc;
GRANT INSERT, UPDATE ON TABLE hr.roles TO hr_svc;
GRANT INSERT, UPDATE ON TABLE task.task_statuses TO task_svc;
GRANT INSERT, UPDATE ON TABLE task.task_priorities TO task_svc;
GRANT INSERT, UPDATE ON TABLE task.roles TO task_svc;
GRANT SELECT              ON iam.departments TO app_user, tenant_admin;
GRANT INSERT, UPDATE      ON iam.departments TO app_user, hr_svc;
GRANT SELECT ON iam.capabilities TO app_user, tenant_admin;
GRANT SELECT                        ON iam.role_capabilities TO app_user, tenant_admin;
GRANT INSERT, UPDATE, DELETE        ON iam.role_capabilities TO app_user;
